import{_ as e,o,c as i,a5 as t}from"./chunks/framework.CXvGqWf0.js";const p=JSON.parse('{"title":"漫画 · 第 58 话 合成层与 GPU 加速的真实条件","description":"","frontmatter":{},"headers":[],"relativePath":"comics/mechanism/EP.58-compositing-gpu.md","filePath":"comics/mechanism/EP.58-compositing-gpu.md","lastUpdated":1793853676000}'),r={name:"comics/mechanism/EP.58-compositing-gpu.md"};function l(n,a,c,s,d,h){return o(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="漫画-·-第-58-话-合成层与-gpu-加速的真实条件" tabindex="-1">漫画 · 第 58 话 合成层与 GPU 加速的真实条件 <a class="header-anchor" href="#漫画-·-第-58-话-合成层与-gpu-加速的真实条件" aria-label="Permalink to &quot;漫画 · 第 58 话 合成层与 GPU 加速的真实条件&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/mechanism/04-compositing-and-gpu">docs/mechanism/04-compositing-and-gpu.md</a> ｜ 原画：<a href="./EP.58-compositing-gpu.svg">EP.58-compositing-gpu.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师。本话她给全站卡片批量加上 <code>translateZ(0)</code> 和 <code>will-change</code>，坚信“提层就快”。</li><li><strong>标签君</strong>：结构师。负责打开 Layers 面板，用层数与显存把“加速”的真相摆出来。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>像素酱听说“GPU 加速”能救低端机，于是给 80 张卡片全部加 <code>will-change: transform</code>。上线后滚动反而更卡，手机还发烫。标签君打开 Layers 面板：80 多个合成层，纹理吃掉近 200MB 显存。删掉常驻提示、只给正在动画的元素临时提层后，帧率从 25 回到 58。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>满屏卡片都标了 <code>will-change</code>，浏览器为每张卡保留独立纹理。滚动时合成线程不停上传、回收纹理，带宽与显存都吃紧。像素酱看到的“层数很多”以为是好事，实际是典型的层爆炸：每层都要栅格化、都要占显存。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>合成层让元素可以只改变换矩阵或透明度，跳过布局与绘制。但提层有真实条件：3D 变换、<code>will-change</code> 提示、与动画层重叠、fixed、video/canvas、filter 等。普通元素写个静态 <code>transform</code> 不一定提层。而且提层不省首次栅格化，也不省显存，层越多合成与带宽开销越大。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>正确姿势是按需：交互开始前加 <code>will-change</code>，<code>transitionend</code> 后撤掉；动画只碰 transform/opacity；大面积阴影改用伪元素 opacity；屏外模块用 <code>content-visibility</code>。像素酱把 80 层降到 12 层，显存降一个量级，滚动恢复 55–60fps。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>有 transform 样式 ≠ 自动提层；浏览器按需判断，别把提示当命令。</li><li><code>will-change</code> 用完即撤，常驻会保留纹理与层，移动端代价高。</li><li>合成友好动画只碰 transform/opacity；不要过渡 box-shadow、width、left。</li><li>用 DevTools Layers 面板看层数与显存，不要凭代码猜。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：为什么加了 <code>translateZ(0)</code> 后，文字有时反而变模糊？</p><p><strong>答</strong>：元素被提升为独立合成层后，文字在该层的纹理上栅格化。若图层缩放比例、像素对齐与主层不同，纹理会按不同采样率生成，看起来就模糊。关键文本不应强制提层；必须提层时避免非整数缩放，并在真机上检查清晰度。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>left 与 transform 双轨道帧率对比、will-change 开关：<a href="./../../examples/mechanism/04-compositing-and-gpu">examples/mechanism/04-compositing-and-gpu</a></li><li>打开 DevTools → Layers，观察两个轨道元素的层归属与显存估算。</li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>层也提了，动画还是偶尔抖。第 59 话《渲染时序：rAF、ResizeObserver 循环与任务切分》——把每一帧安排明白。</p>',22)])])}const u=e(r,[["render",l]]);export{p as __pageData,u as default};
